// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CheckIcon, CopyIcon } from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, COPIED, INPUTS, LABELS, ROWS } from './script'

const SHAPES = [
  '42% 58% 63% 37% / 41% 44% 56% 59%',
  '62% 38% 34% 66% / 58% 31% 69% 42%',
  '35% 65% 48% 52% / 62% 54% 46% 38%',
]

const build: Build = ({ tl, q, step, final, move, click, type, scramble, wait, cursorOut }) => {
  const apply = (index: number) => {
    const { hex } = INPUTS[index]
    tl.to(
      [q('swatch'), q('blob')],
      { backgroundColor: hex, duration: 0.6, ease: 'power2.inOut' },
      '<',
    )
    tl.to(
      q('blob'),
      { borderRadius: SHAPES[index], rotation: index * 40, duration: 0.9, ease: 'power3.inOut' },
      '<',
    )
    tl.to(q('glow'), { backgroundColor: hex, duration: 0.6 }, '<')
    scramble('blob-hex', hex.toUpperCase(), { at: '<', duration: 0.6, chars: '0123456789ABCDEF' })
    ROWS[index].forEach((row, rowIndex) =>
      scramble(`value-${rowIndex}`, row.value, {
        at: rowIndex === 0 ? '<' : '<0.05',
        duration: 0.6,
        chars: '0123456789%',
      }),
    )
  }

  step(0)
  move('input', { ax: 0.2, at: 0.2 })
  click('input')
  type('input-text', INPUTS[0].typed, { speed: 0.06 })
  tl.fromTo(
    [q('swatch'), q('blob'), q('rows')],
    { opacity: 0, scale: 0.9 },
    { opacity: 1, scale: 1, duration: 0.4, ease: 'back.out(2)' },
  )
  apply(0)

  INPUTS.slice(1).forEach((input, offset) => {
    const index = offset + 1
    step(index, '+=0.6')
    tl.to(q('input-text'), { text: '', duration: 0.2 })
    type('input-text', input.typed, { speed: 0.05 })
    apply(index)
  })

  step(3, '+=0.6')
  move(`copy-${COPIED}`)
  click(`copy-${COPIED}`)
  tl.to(q(`copy-${COPIED}`), { opacity: 0, duration: 0.1 }, '<')
  tl.fromTo(
    q(`done-${COPIED}`),
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.25, ease: 'back.out(3)' },
    '<',
  )
  tl.to(q(`row-${COPIED}`), { borderColor: 'rgba(244,114,182,0.6)', duration: 0.2 }, '<')
  cursorOut('+=0.3')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="Color Converter turning HEX, hsl() and a colour name into six formats at once"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full gap-4">
          <div className="flex min-w-0 flex-1 flex-col gap-2">
            <div className="flex items-center gap-2">
              <span
                data-d="swatch"
                className="size-8 shrink-0 rounded-md border border-ink/10 bg-[#3b82f6] opacity-0"
              />
              <span
                data-d="input"
                className="flex h-8 flex-1 items-center rounded-md border border-line-strong bg-canvas/80 px-2.5 font-mono text-[11px] text-ink"
              >
                <span data-d="input-text" />
                <span className="ml-px h-3.5 w-px animate-pulse bg-ink-soft" />
              </span>
            </div>
            <p className="text-[9.5px] text-[var(--accent)]">Try example</p>
            <div data-d="rows" className="space-y-1 opacity-0">
              {LABELS.map((label, index) => (
                <div
                  key={label}
                  data-d={`row-${index}`}
                  className="flex h-7 items-center gap-2 rounded-md border border-line bg-ink/[0.03] px-2"
                >
                  <span className="w-9 text-[9.5px] font-medium text-muted">{label}</span>
                  <code
                    data-d={`value-${index}`}
                    className="min-w-0 flex-1 truncate font-mono text-[10px] text-ink"
                  />
                  <span className="relative size-3 text-muted">
                    <span data-d={`copy-${index}`} className="absolute inset-0">
                      <CopyIcon className="size-3" />
                    </span>
                    <span
                      data-d={`done-${index}`}
                      className="absolute inset-0 text-[var(--accent)] opacity-0"
                    >
                      <CheckIcon className="size-3" />
                    </span>
                  </span>
                </div>
              ))}
            </div>
          </div>
          <div className="relative flex w-[150px] shrink-0 flex-col items-center justify-center gap-3">
            <span
              data-d="glow"
              className="absolute size-28 rounded-full bg-[#3b82f6] opacity-40 blur-2xl"
            />
            <span
              data-d="blob"
              className="relative size-28 bg-[#3b82f6] opacity-0"
              style={{ borderRadius: SHAPES[0] }}
            />
            <span
              data-d="blob-hex"
              className="relative font-mono text-[12px] font-semibold tracking-wider text-ink"
            >
              {INPUTS[0].hex.toUpperCase()}
            </span>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
